describe('Notification Badge Count', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's homepage
    });

    it('should display the correct badge count on the notification bell icon', () => {
        // Assuming the notification bell has a data attribute for testing
        cy.get('[data-testid="notification-bell"]').should('exist');
        cy.get('[data-testid="notification-badge"]').should('exist').and('contain', '3'); // Example count
    });

    it('should not display a badge when there are no notifications', () => {
        // Simulate no notifications
        cy.intercept('GET', '/api/notifications', []).as('getNotifications');
        cy.wait('@getNotifications');

        cy.get('[data-testid="notification-bell"]').should('exist');
        cy.get('[data-testid="notification-badge"]').should('not.exist');
    });
});
